import {playerMail,mailUrl} from './mail-trigger-hooks.js';
/** Browser-local social chambers. Sharing and moderation are demonstrable, not remote access controls. */
export function createCommunity(ctx) {
  const c=ctx,e=c.esc,I=c.icon,B=c.button;
  const labels={public:'Openbare kamer',private:'Privékamer',tournament:'Toernooikamer'};
  let filter='all',query='',moderatorDemo=false,moderationRoomId=null,serial=0;
  const me=1;
  const uid=()=>Date.now()*100+(serial++%100);
  const now=()=>new Date().toISOString();
  const state=()=>c.db.play.community;
  const activeScope=()=>typeof c.scopeId==='function'?(Number(c.scopeId())||null):undefined;
  const inScope=r=>activeScope()===undefined||(Number(r.clubId)||null)===activeScope();
  const scopeLabel=()=>typeof c.scopeName==='function'?c.scopeName():(activeScope()?'de club':'Dartflow');
  const member=(r,id=me)=>r.members.find(m=>m.id===id);
  const clubAccess=(r,id=me)=>!r.clubId||!!c.db.play.clubs?.items?.some(club=>club.id===Number(r.clubId)&&club.members?.some(m=>Number(typeof m==='object'?m.id:m)===id));
  const blocked=id=>(c.db.play.social?.blocked||[]).includes(Number(id));
  const isHost=r=>r.ownerId===me||(moderatorDemo&&moderationRoomId===r.id);
  const isModerator=r=>isHost(r)||c.db.role==='admin'||member(r)?.role==='moderator';
  const isMuted=(r,id=me)=>Number(member(r,id)?.mutedUntil||0)>Date.now();
  const displayName=id=>id===0?'Dartflow':c.P(id).name;
  const time=d=>new Intl.DateTimeFormat('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'}).format(new Date(d));
  const note=text=>`<div class="notice">${I('info')}${text}</div>`;
  const roomById=id=>state().rooms.find(r=>r.id===Number(id));
  const codeRoom=code=>state().rooms.find(r=>r.code.toUpperCase()===String(code||'').trim().toUpperCase()&&!r.archived);
  const saveRender=()=>{c.save();c.render();};
  const addSystem=(r,text)=>r.messages.push({id:uid(),userId:0,text,date:now(),deleted:false,system:true});
  function init(){
    c.db.play??={};
    if(!c.db.play.community){
      const members=(ids,host)=>ids.map(id=>({id,role:id===host?'host':id===5?'moderator':'member',mutedUntil:0}));
      const make=(id,name,type,maxMembers,ids,host,description,code)=>({id,name,type,maxMembers,members:members(ids,host),code,description,ownerId:host,messages:[],bans:[],slowMode:0,challenges:[],joined:ids.includes(me),invitedIds:[],archived:false,createdAt:now(),lastSentBy:{}});
      const r1=make(1,'De Oche','public',16,[2,3,4,5,6,7,8,9],9,'De digitale dartkantine. Maak een praatje, zoek een tegenstander of kijk mee.','DR-OCHE');
      const r2=make(2,'Rustig beginnen','public',12,[2,3,4,6,10,12],10,'Voor nieuwe spelers en ontspannen oefenpotjes. Alle niveaus zijn welkom.','DR-START');
      const r3=make(3,'Vrijdag met de vrienden','private',6,[1,2,5],1,'Onze eigen tafel. Bijkletsen, elkaar uitdagen en nog één revanche.','DR-VRIENDEN');
      const r4=make(4,'Puinruimers Open','tournament',32,Array.from({length:24},(_,i)=>i+1),9,'De gezamenlijke toernooikamer. Check in, spreek af en volg de volgende ronde.','DR-OPEN');
      r4.clubId=701;
      const r5=make(5,'Besloten trainingsgroep','private',8,[9,10,11,12],9,'Een besloten kamer voor een vaste trainingsgroep.','DR-TRAIN');
      const seedMessage=(r,userId,text)=>r.messages.push({id:uid(),userId,text,date:new Date(Date.now()-6*60000+(r.messages.length*60000)).toISOString(),deleted:false});
      seedMessage(r1,9,'Welkom in De Oche! Hier vind je altijd wel een volgend potje.');
      seedMessage(r1,2,'Iemand zin in een 501 best-of-5? Gewoon een relaxed oefenpotje.');
      seedMessage(r1,5,'Ik ben er ook. Eerst even mijn doubles warmgooien.');
      seedMessage(r2,10,'Hier mag je rustig oefenen. Vraag gerust om een rematch!');
      seedMessage(r2,3,'Wie speelt er mee? Mijn gemiddelde zit rond de 40.');
      seedMessage(r3,1,'De kamer is open. Nog zes legs voor het eten?');
      seedMessage(r3,2,'Ik ben erbij. Bord en camera staan klaar.');
      seedMessage(r3,5,'Eerst een praatje, dan gooien!');
      seedMessage(r4,9,'Welkom bij de Puinruimers Open. Check ook even in bij de toernooizaal.');
      seedMessage(r4,4,'Succes allemaal vanavond!');
      seedMessage(r5,9,'Dit is alleen zichtbaar na een geldige uitnodiging.');
      c.db.play.community={rooms:[r1,r2,r3,r4,r5]};
    }
    for(const r of state().rooms){if(r.clubId===702&&r.name==='DartRush Social Club · Clubhuis')r.name='Dartflow Social Club · Clubhuis';if(r.clubId===702&&r.description==='De privéclubkamer van DartRush Social Club')r.description='De privéclubkamer van Dartflow Social Club';if(r.id===4&&r.name==='Puinruimers Open'&&(r.clubId===undefined||r.clubId===1))r.clubId=701;r.members??=[];r.messages??=[];r.bans??=[];r.challenges??=[];r.invitedIds??=[];r.lastSentBy??={};r.joined=!!member(r);}
  }

  function createRoom(options={}){
    init();
    const ownerId=Number(options.ownerId)||me;
    const sourceMembers=options.memberIds||options.members||[me];
    const ids=[...new Set(sourceMembers.map(v=>Number(typeof v==='object'?v.id:v)).filter(id=>id>0&&c.db.players.some(p=>p.id===id)))];
    if(!ids.includes(ownerId))ids.unshift(ownerId);
    const maxMembers=Math.min(64,Math.max(2,ids.length,Number(options.maxMembers)||8));
    const id=uid();
    const r={id,name:String(options.name||'Nieuwe dartkamer').trim().slice(0,60),type:Object.hasOwn(labels,options.type)?options.type:'private',maxMembers,members:ids.slice(0,maxMembers).map(id=>({id,role:id===ownerId?'host':sourceMembers.find(m=>typeof m==='object'&&m.id===id)?.role==='moderator'?'moderator':'member',mutedUntil:0})),code:String(options.code||('DR-'+id.toString(36).slice(-6).toUpperCase())).slice(0,30),description:String(options.description||'').trim().slice(0,160),ownerId,messages:[],bans:[],slowMode:0,challenges:[],joined:ids.includes(me),invitedIds:[],createdAt:now(),lastSentBy:{},archived:false};
    const roomClubId=options.clubId===undefined?activeScope():options.clubId;
    if(roomClubId!==null&&roomClubId!==undefined&&Number(roomClubId)>0)r.clubId=Number(roomClubId);
    if(options.tournamentId)r.tournamentId=Number(options.tournamentId);
    addSystem(r,`${displayName(ownerId)} heeft de kamer geopend.`);
    state().rooms.unshift(r);
    return id;
  }
  function getRoute(){const value=c.routeParam?.();return value===undefined||value===null||value===''?null:value;}
  function selected(){init();const value=getRoute();if(value===null)return null;return roomById(value)||codeRoom(value);}
  function canSend(r){return clubAccess(r)&&!!member(r)&&!r.bans.includes(me)&&!isMuted(r)&&!r.archived;}
  function refusal(r){if(!clubAccess(r))return'Word eerst lid van de club om deze kamer te gebruiken.';if(r.archived)return'Deze kamer is gesloten.';if(r.bans.includes(me))return'Je bent geblokkeerd voor deze kamer.';if(!member(r))return'Neem eerst deel aan de kamer.';if(isMuted(r))return'Je bent tijdelijk gedempt in deze kamer.';return'';}
  function join(r,withCode=false){
    if(!r||r.archived){c.toast('Deze kamer is niet beschikbaar.');return false;}
    if(!clubAccess(r)){c.toast('Word eerst lid van de club om deze kamer te gebruiken.');return false;}
    if(member(r)){c.go('community/'+r.id);return true;}
    if(r.bans.includes(me)){c.toast('Je bent geblokkeerd voor deze kamer.');return false;}
    if(r.type==='private'&&!withCode){joinForm();return false;}
    if(r.members.length>=r.maxMembers){c.toast('Deze kamer zit vol. Probeer later opnieuw.');return false;}
    r.members.push({id:me,role:'member',mutedUntil:0});r.joined=true;addSystem(r,`${displayName(me)} is aangesloten.`);c.save();c.closeModal();c.go('community/'+r.id);return true;
  }
  function roomCard(r){
    const joined=!!member(r),privateLocked=r.type==='private'&&!joined,full=r.members.length>=r.maxMembers;
    return `<article class="panel dr-room-card ${privateLocked?'locked':''}"><div class="dr-inline dr-room-card-top"><span class="dr-action-icon">${I(r.type==='private'?'shield':r.type==='tournament'?'trophy':'users')}</span>${c.badge(labels[r.type],r.type==='private'?'pending':r.type==='tournament'?'blue':'live')}</div><h2>${privateLocked?'Een besloten kamer':e(r.name)}</h2><p class="dr-meta">${privateLocked?'Deze kamer open je met een uitnodigingscode. Alleen leden kunnen de chat en deelnemers zien.':e(r.description)}</p><div class="dr-room-capacity"><span>${I('users')} ${r.members.length} / ${r.maxMembers} personen</span>${joined?c.badge('Jij bent erbij','approved'):full?c.badge('Vol','red'):c.badge((r.maxMembers-r.members.length)+' plekken vrij')}</div><div class="progress"><span style="width:${Math.round(r.members.length/r.maxMembers*100)}%"></span></div><div class="dr-community-actions">${joined?B('Open kamer '+I('arrow'),'community-open','gold',`data-id="${r.id}"`):privateLocked?B(I('shield')+' Met code deelnemen','community-code','ghost'):B(full?'Kamer is vol':'Binnenkomen '+I('arrow'),'community-join','gold',`data-id="${r.id}" ${full?'disabled':''}`)}${joined&&r.ownerId===me?B(I('settings'),'community-settings','ghost',`data-id="${r.id}" aria-label="Kamerinstellingen"`):''}</div></article>`;
  }
  function lobby(){
    const rooms=state().rooms.filter(r=>!r.archived&&inScope(r)).filter(r=>filter==='all'||filter==='mine'?filter==='all'||!!member(r):r.type===filter).filter(r=>!query||((r.type==='private'&&!member(r)?'besloten kamer':r.name)+' '+labels[r.type]).toLowerCase().includes(query.toLowerCase()));
    return c.header('Kamers',`Ontmoet darters en spreek wedstrijden af binnen ${e(scopeLabel())}.`,`<div class="dr-inline">${B('Uitnodigingscode','community-code','ghost')}${B(I('plus')+' Kamer maken','community-create','gold')}</div>`)+`<div class="toolbar dr-list-toolbar"><div class="tabs">${[['all','Alle kamers'],['mine','Mijn kamers'],['public','Openbaar'],['private','Privé'],['tournament','Toernooien']].map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-action="community-filter" data-value="${id}">${label}</button>`).join('')}</div><form class="dr-inline dr-list-search" data-form="community-search"><div class="input-wrap">${I('search')}<input class="input" name="query" value="${e(query)}" placeholder="Zoek een kamer…" aria-label="Zoek een kamer"></div><button class="btn ghost small" type="submit">Zoeken</button></form></div><div class="dr-grid dr-grid-3 dr-card-grid">${rooms.map(roomCard).join('')}</div>${!rooms.length?c.empty('Nog geen kamers gevonden','Maak zelf een kamer of gebruik een uitnodigingscode.','users'):''}<div class="dr-demo-line dr-inline" style="margin-top:20px">${I('info')}Lokale demo: chat en kamers synchroniseren tussen tabbladen op dit apparaat. De andere aanwezigen zijn voorbeeldspelers.</div>`;
  }
  function challengeMarkup(r,msg){const x=r.challenges.find(x=>x.id===msg.challengeId);if(!x)return'';const pending=x.status==='pending',fromMe=x.from===me,toMe=x.to===me;return `<div class="dr-challenge-card"><div class="dr-inline">${I('target')}<strong>${e(displayName(x.from))} daagt ${e(displayName(x.to))} uit</strong>${c.badge({pending:'Uitnodiging',accepted:'Geaccepteerd',declined:'Afgewezen',cancelled:'Ingetrokken'}[x.status],pending?'pending':x.status==='accepted'?'approved':'finished')}</div><p>${x.startScore} · Best of ${x.bestOf} · ${x.ranked?'Competitief':'Oefenwedstrijd'} · Op afstand</p><div class="dr-inline dr-wrap">${pending&&toMe?B('Uitdaging accepteren','community-accept','gold small',`data-id="${r.id}" data-challenge="${x.id}"`):''}${pending&&fromMe?B(`Accepteer als ${e(c.short(x.to))} (demo)`,'community-accept','gold small',`data-id="${r.id}" data-challenge="${x.id}"`):''}${pending&&(fromMe||isModerator(r))?B('Intrekken','community-cancel','ghost small',`data-id="${r.id}" data-challenge="${x.id}"`):''}${pending&&toMe?B('Afwijzen','community-decline','ghost small',`data-id="${r.id}" data-challenge="${x.id}"`):''}${x.matchId?B('Naar de wedstrijd '+I('arrow'),'community-match','gold small',`data-match="${x.matchId}"`):''}</div></div>`;}
  function messageMarkup(r,msg){
    if(msg.system)return `<div class="dr-community-system">${I('info')} ${e(msg.text)} <time>${time(msg.date)}</time></div>`;
    const author=displayName(msg.userId),mod=isModerator(r);return `<article class="dr-community-message ${msg.userId===me?'own':''} ${msg.deleted?'deleted':''}"><div class="dr-inline">${c.avatar(msg.userId,'sm')}<strong>${e(author)}</strong>${member(r,msg.userId)?.role==='host'?c.badge('Host'):member(r,msg.userId)?.role==='moderator'?c.badge('Moderator','blue'):''}<time>${time(msg.date)}</time>${mod&&!msg.deleted?`<button class="text-link" data-action="community-delete-message" data-id="${r.id}" data-message="${msg.id}" aria-label="Bericht van ${e(author)} verwijderen">${I('close')}</button>`:''}</div>${msg.deleted?'<p>Dit bericht is verwijderd door een moderator.</p>':msg.kind==='challenge'?challengeMarkup(r,msg):`<p>${e(msg.text)}</p>`}</article>`;
  }
  function memberMarkup(r,m){const self=m.id===me,mod=isModerator(r),host=isHost(r),isOwner=m.id===r.ownerId;return `<article class="dr-community-member"><div class="dr-inline">${c.avatar(m.id)}<div><strong>${e(displayName(m.id))}${self?' · jij':''}</strong><small>${isOwner?'Host':m.role==='moderator'?'Moderator':isMuted(r,m.id)?'Tijdelijk gedempt':'Online · demo'}</small></div></div><div class="dr-community-member-actions">${!self&&!blocked(m.id)?B('Uitdagen','community-challenge','gold small',`data-id="${r.id}" data-player="${m.id}"`):''}${!self?`<button class="text-link" data-action="community-private-friend" data-player="${m.id}" aria-label="Privékamer met ${e(c.short(m.id))}">${I('shield')}</button>`:''}${mod&&!self&&!isOwner?`<button class="icon-btn" data-action="community-moderate" data-id="${r.id}" data-player="${m.id}" aria-label="Beheer ${e(displayName(m.id))}">${I('settings')}</button>`:''}</div></article>`;}
  function roomView(r){
    const joined=!!member(r),mod=isModerator(r),host=isHost(r),muted=isMuted(r),can=canSend(r),denied=refusal(r);
    return c.header(e(r.name),e(r.description),`<div class="dr-inline">${B(I('left')+' Alle kamers','community-back','ghost')}${host?B(I('settings')+' Beheren','community-settings','ghost',`data-id="${r.id}"`):''}</div>`)+`<div class="dr-community-room-meta"><div class="dr-inline dr-wrap">${c.badge(labels[r.type],r.type==='private'?'pending':'live')}${c.badge(`${r.members.length}/${r.maxMembers} personen`)}${r.slowMode?c.badge(`Langzaam chatten · ${r.slowMode}s`):''}${moderatorDemo&&moderationRoomId===r.id?c.badge('Moderatorweergave · demo','blue'):''}</div><div class="dr-inline dr-wrap">${r.type==='tournament'?B(I('trophy')+' Toernooizaal','community-hall','ghost small'):''}${joined?B(I('plus')+' Uitnodigen','community-invite','ghost small',`data-id="${r.id}"`):B('Deelnemen','community-join','gold small',`data-id="${r.id}"`)}${joined?B('Kamer verlaten','community-leave','ghost small',`data-id="${r.id}"`):''}</div></div><div class="dr-community-layout"><section class="panel dr-community-chat"><div class="section-heading"><h2>Gesprek</h2>${joined?B('Demo-reactie','community-demo-reply','ghost small',`data-id="${r.id}"`):c.badge('Je kijkt mee')}</div><div class="dr-community-messages" aria-live="polite" role="log">${r.messages.length?r.messages.slice(-70).map(m=>messageMarkup(r,m)).join(''):'<div class="dr-empty-inline">Er zijn nog geen berichten.</div>'}</div>${r.invitedIds?.length&&host?`<div class="dr-community-pending"><small class="dr-meta">Uitnodigingen klaar in de demo</small><div class="dr-inline dr-wrap">${r.invitedIds.filter(id=>!member(r,id)).map(id=>B(`Simuleer ${e(c.short(id))} aansluiten`,'community-simulate-join','ghost small',`data-id="${r.id}" data-player="${id}"`)).join('')}</div></div>`:''}<form class="dr-community-input" data-form="community-message"><input type="hidden" name="roomId" value="${r.id}"><label class="field">${can?'Een bericht aan de kamer':e(denied)}<input class="input" name="text" maxlength="500" required autocomplete="off" placeholder="Zeg hallo of spreek een potje af…" ${can?'':'disabled'}></label><button class="btn gold" type="submit" ${can?'':'disabled'}>${I('arrow')} Versturen</button></form><div class="dr-inline dr-demo-line">${I('info')}Lokaal demogesprek · geen externe berichten · ${r.type==='private'?'alleen voor kamerleden':'andere aanwezigen zijn voorbeeldspelers'}</div></section><aside class="panel dr-community-members"><div class="section-heading"><h2>Deelnemers</h2><span class="dr-meta">${r.members.length}/${r.maxMembers}</span></div>${r.members.map(m=>memberMarkup(r,m)).join('')}${joined&&!isHost(r)&&c.db.role!=='admin'?`<div class="dr-section-gap">${B(moderatorDemo?'Moderatorweergave uit':'Bekijk als moderator (demo)','community-mod-demo','ghost block small')}</div>`:''}${host&&r.bans.length?`<div class="dr-section-gap"><strong class="dr-meta">Geblokkeerd in deze kamer</strong>${r.bans.map(id=>`<div class="dr-inline" style="margin-top:8px"><span>${e(displayName(id))}</span>${B('Deblokkeer','community-unban','ghost small',`data-id="${r.id}" data-player="${id}"`)}</div>`).join('')}</div>`:''}</aside></div>`;
  }
  function inviteGate(r,hasCode){return c.header('Een besloten tafel. <em>Alleen op uitnodiging.</em>',hasCode?`Je hebt een uitnodiging voor ${e(r.name)}.`:'De chat en deelnemers zijn alleen zichtbaar voor kamerleden.',B('Alle kamers','community-back','ghost'))+`<section class="panel" style="max-width:560px;margin:auto">${note(hasCode?`Uitnodigingscode herkend. Er zijn ${r.maxMembers-r.members.length} plaatsen beschikbaar.`:'Vraag de host om een kameruitnodiging of voer je code in.')}<div class="modal-actions">${hasCode?B('Deelnemen aan deze kamer','community-redeem','gold',`data-code="${e(r.code)}"`):B('Uitnodigingscode invoeren','community-code','gold')}</div></section>`;}
  function view(){init();const param=getRoute();if(param===null)return lobby();const r=selected();if(!r||r.archived)return c.header('Deze kamer is niet beschikbaar.','De kamer bestaat niet in deze lokale demo.',B('Alle kamers','community-back','gold'));if(!clubAccess(r))return c.header('Deze kamer hoort bij een club.','Word eerst clublid om aan dit besloten gesprek deel te nemen.',B('Naar de clubs','community-clubs','gold'));if(r.bans.includes(me))return c.header('Toegang geweigerd.','Je bent geblokkeerd voor deze kamer.',B('Alle kamers','community-back','ghost'));if(r.type==='private'&&!member(r))return inviteGate(r,String(param).toUpperCase()===r.code.toUpperCase());return roomView(r);}
  function createForm(preset={}){const friends=c.db.players.filter(p=>p.status==='approved'&&p.id!==me&&!blocked(p.id)&&clubAccess({clubId:activeScope()},p.id));c.showModal('Schuif je eigen tafel aan.','Een openbare ontmoetingsplek, een besloten vriendenkring of een toernooikamer.',`<form data-form="community-create"><label class="field">Kamernaam<input class="input" name="name" required maxlength="60" placeholder="Bijvoorbeeld Onze vrijdagavond" value="${e(preset.name||'')}"></label><div class="field-row"><label class="field">Soort kamer<select name="type">${Object.entries(labels).map(([id,label])=>`<option value="${id}" ${id===(preset.type||'public')?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Maximaal personen<input class="input" name="maxMembers" type="number" min="2" max="64" step="1" required value="${preset.maxMembers||8}"></label></div><label class="field">Omschrijving<input class="input" name="description" maxlength="160" placeholder="Wat voor potjes spelen jullie hier?"></label><label class="field">Vriend uitnodigen (optioneel)<select name="friend"><option value="">Nog niemand</option>${friends.map(p=>`<option value="${p.id}" ${p.id===preset.friend?'selected':''}>${e(p.name)}</option>`).join('')}</select></label>${note('Uitnodigingen blijven lokaal in de demo. Met de simulatieknop kun je een vriend laten aansluiten en de bezetting testen.')}<div id="community-error" class="inline-error" role="alert"></div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button type="submit" class="btn gold">${I('plus')} Kamer maken</button></div></form>`);}
  function joinForm(){c.showModal('Er staat een stoel voor je klaar.','Gebruik de uitnodigingscode van een bestaande demokamer.',`<form data-form="community-code"><label class="field">Kamercode<input class="input" name="code" required maxlength="30" placeholder="Bijvoorbeeld DR-VRIENDEN" autocomplete="off"></label><div id="community-error" class="inline-error" role="alert"></div>${note('Deze code werkt voor kamers die in deze browser zijn aangemaakt. Echt chatten tussen verschillende apparaten wordt later gekoppeld.')}<div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold" type="submit">Deelnemen ${I('arrow')}</button></div></form>`);}
  function inviteForm(r){if(!member(r))return;c.showModal('Neem je dartmaatjes mee.','Kopieer de kamercode of de uitnodigingslink.',`<div class="dr-invitation"><small class="dr-meta">KAMERCODE</small><strong style="display:block;font-family:var(--display);font-size:34px;color:var(--gold);letter-spacing:2px">${e(r.code)}</strong><div class="dr-inline">${B('Code kopiëren','community-copy-code','gold small',`data-id="${r.id}"`)}${B('Link kopiëren','community-copy-link','ghost small',`data-id="${r.id}"`)}</div></div><p class="dr-meta">${r.members.length}/${r.maxMembers} plaatsen bezet. ${r.type==='private'?'Alleen spelers met een geldige uitnodiging kunnen deelnemen.':''}</p>${note('De link opent de lokale kamer als die in dezelfde browser beschikbaar is. Er wordt geen echte uitnodiging verstuurd.')}<div class="modal-actions">${B('Sluiten','close-modal','gold')}</div>`);}
  function settings(r){if(!isHost(r)){c.toast('Alleen de host kan de kamerinstellingen wijzigen.');return;}c.showModal('De tafel staat onder jouw beheer.','Pas de kamer en de chatregels aan.',`<form data-form="community-settings"><input type="hidden" name="roomId" value="${r.id}"><label class="field">Kamernaam<input class="input" name="name" required maxlength="60" value="${e(r.name)}"></label><label class="field">Omschrijving<input class="input" name="description" maxlength="160" value="${e(r.description)}"></label><div class="field-row"><label class="field">Kamer<select name="type">${Object.entries(labels).map(([id,label])=>`<option value="${id}" ${r.type===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Maximaal personen<input name="maxMembers" class="input" required type="number" min="${Math.max(2,r.members.length)}" max="64" value="${r.maxMembers}"></label></div><label class="field">Langzaam chatten<select name="slowMode">${[[0,'Uit'],[10,'Maximaal één bericht per 10 seconden'],[30,'Maximaal één bericht per 30 seconden']].map(([v,t])=>`<option value="${v}" ${r.slowMode===v?'selected':''}>${t}</option>`).join('')}</select></label><div id="community-error" class="inline-error" role="alert"></div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold" type="submit">Instellingen opslaan</button></div></form>`);}
  function moderate(r,id){const target=member(r,id);if(!isModerator(r)||!target||id===me||id===r.ownerId){c.toast('Deze deelnemer kun je niet beheren.');return;}c.showModal(`Beheer ${e(displayName(id))}.`,'Moderatieacties worden zichtbaar bijgehouden in de kamer.',`<div class="dr-grid">${B(isMuted(r,id)?'Dempen opheffen':'5 minuten dempen','community-mute','ghost',`data-id="${r.id}" data-player="${id}"`)}${B('Uit de kamer verwijderen','community-kick','ghost',`data-id="${r.id}" data-player="${id}"`)}${B('Blokkeren voor deze kamer','community-ban','danger',`data-id="${r.id}" data-player="${id}"`)}${isHost(r)?B(target.role==='moderator'?'Moderatorrol intrekken':'Moderator maken','community-promote','gold',`data-id="${r.id}" data-player="${id}"`):''}</div><div class="modal-actions">${B('Sluiten','close-modal','ghost')}</div>`);}
  function challengeForm(r,id){if(!canSend(r)){c.toast(refusal(r));return;}if(id===me||!member(r,id)||blocked(id)){c.toast('Deze speler kun je niet uitdagen.');return;}c.showModal(`${e(c.short(id))}, potje gooien?`,'Plaats een uitnodiging in de kamer. De tegenstander kan daarna instappen.',`<form data-form="community-challenge"><input type="hidden" name="roomId" value="${r.id}"><input type="hidden" name="opponentId" value="${id}"><div class="field-row"><label class="field">Spel<select name="startScore"><option>301</option><option selected>501</option><option>701</option></select></label><label class="field">Best of<select name="bestOf">${[1,3,5,7,9].map(n=>`<option ${n===5?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="field">Wedstrijdvorm<select name="ranked"><option value="no">Oefenwedstrijd</option><option value="yes">Competitief · demoranking</option></select></label><div id="community-error" class="inline-error" role="alert"></div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold" type="submit">${I('target')} Uitdaging plaatsen</button></div></form>`);}
  async function copy(text){try{await navigator.clipboard.writeText(text);c.toast('Gekopieerd.');}catch{c.showModal('Kopieer de uitnodiging.','Selecteer de tekst om deze zelf te kopiëren.',`<label class="field">Uitnodiging<input class="input" value="${e(text)}" readonly></label><div class="modal-actions">${B('Sluiten','close-modal','gold')}</div>`);}}
  function handleAction(action,el){if(!action.startsWith('community-'))return false;init();const id=Number(el.dataset.id),r=roomById(id),targetId=Number(el.dataset.player);switch(action){
    case'community-back':moderatorDemo=false;c.go('community');break;
    case'community-filter':filter=el.dataset.value;c.go('community');break;
    case'community-create':createForm();break;
    case'community-code':joinForm();break;
    case'community-open':if(r)c.go('community/'+r.id);break;
    case'community-join':join(r);break;
    case'community-redeem':join(codeRoom(el.dataset.code),true);break;
    case'community-hall':c.go('hall');break;
    case'community-clubs':c.go('clubs');break;
    case'community-mod-demo':{const active=selected();if(!active||!member(active))break;moderatorDemo=!(moderatorDemo&&moderationRoomId===active.id);moderationRoomId=active.id;}c.render();c.toast(moderatorDemo?'Je bekijkt moderatie als demo.':'Je bekijkt de kamer weer als deelnemer.');break;
    case'community-invite':if(r)inviteForm(r);break;
    case'community-copy-code':if(r&&member(r))copy(r.code);break;
    case'community-copy-link':if(r&&member(r))copy(location.origin+'/#community/'+encodeURIComponent(r.code));break;
    case'community-settings':if(r)settings(r);break;
    case'community-moderate':if(r)moderate(r,targetId);break;
    case'community-private-friend':createForm({type:'private',friend:targetId,name:'Dartavond met '+c.short(targetId),maxMembers:4});break;
    case'community-challenge':if(r)challengeForm(r,targetId);break;
    case'community-match':c.go('match/'+Number(el.dataset.match));break;
    case'community-leave':if(!r||!member(r))break;c.showModal('Verlaat je deze kamer?',r.ownerId===me?'Je draagt het beheer over aan een andere deelnemer. Als je alleen bent, wordt de kamer gesloten.':'Je kunt later opnieuw deelnemen, zolang er plaats is.',`<div class="modal-actions">${B('Blijven','close-modal','ghost')}${B('Ja, kamer verlaten','community-confirm-leave','danger',`data-id="${r.id}"`)}</div>`);break;
    case'community-confirm-leave':if(!r||!member(r))break;r.members=r.members.filter(m=>m.id!==me);r.joined=false;if(r.ownerId===me){if(r.members.length){r.ownerId=r.members.find(m=>m.role==='moderator')?.id||r.members[0].id;member(r,r.ownerId).role='host';addSystem(r,`${displayName(r.ownerId)} is de nieuwe host.`);}else r.archived=true;}addSystem(r,`${displayName(me)} heeft de kamer verlaten.`);moderatorDemo=false;c.save();c.closeModal();c.go('community');break;
    case'community-demo-reply':if(!r||!member(r))break;{const responder=r.members.find(m=>m.id!==me&&!isMuted(r,m.id));if(!responder){c.toast('Nog geen andere deelnemer in de demo.');break;}const replies=['Zin in een potje 501? Daag me gerust uit!','Mooie avond om te gooien. Succes aan de oche!','Even die laatste dubbel raken en dan een revanche.'];r.messages.push({id:uid(),userId:responder.id,text:replies[r.messages.length%replies.length]+' · demoreactie',date:now(),deleted:false});saveRender();}break;
    case'community-simulate-join':if(!r||!isHost(r)||!r.invitedIds.includes(targetId)||member(r,targetId))break;if(r.members.length>=r.maxMembers){c.toast('De kamer zit vol.');break;}if(r.bans.includes(targetId)){c.toast('Deze speler is geblokkeerd voor de kamer.');break;}r.members.push({id:targetId,role:'member',mutedUntil:0});r.invitedIds=r.invitedIds.filter(id=>id!==targetId);addSystem(r,`${displayName(targetId)} is aangesloten (demo).`);saveRender();break;
    case'community-delete-message':if(!r||!isModerator(r))break;{const msg=r.messages.find(m=>m.id===Number(el.dataset.message));if(!msg||msg.system||msg.deleted)break;msg.deleted=true;msg.deletedBy=me;saveRender();c.toast('Bericht verwijderd.');}break;
    case'community-unban':if(!r||!isHost(r))break;r.bans=r.bans.filter(id=>id!==targetId);addSystem(r,`${displayName(targetId)} kan weer deelnemen aan de kamer.`);saveRender();break;
    case'community-mute':case'community-kick':case'community-ban':case'community-promote':{if(!r||!isModerator(r)||targetId===me||targetId===r.ownerId||!member(r,targetId))break;const m=member(r,targetId);if(action==='community-promote'){if(!isHost(r))break;m.role=m.role==='moderator'?'member':'moderator';addSystem(r,`${displayName(targetId)} is nu ${m.role==='moderator'?'moderator':'deelnemer'}.`);}else if(action==='community-mute'){m.mutedUntil=isMuted(r,targetId)?0:Date.now()+5*60000;addSystem(r,`${displayName(targetId)} ${m.mutedUntil?'is vijf minuten gedempt':'kan weer chatten'}.`);}else{r.members=r.members.filter(m=>m.id!==targetId);if(action==='community-ban'&&!r.bans.includes(targetId))r.bans.push(targetId);for(const x of r.challenges)if(x.status==='pending'&&(x.to===targetId||x.from===targetId))x.status='cancelled';addSystem(r,`${displayName(targetId)} is ${action==='community-ban'?'geblokkeerd voor':'verwijderd uit'} de kamer.`);}playerMail(c,'moderation-notice',`room:${r.id}:moderation:${r.messages.at(-1)?.id}`,r.clubId,targetId,{roomName:r.name,status:action==='community-promote'?(m.role==='moderator'?'Moderator':'Deelnemer'):action==='community-mute'?(m.mutedUntil?'Tijdelijk gedempt':'Dempen opgeheven'):action==='community-ban'?'Geblokkeerd':'Verwijderd',reason:action==='community-promote'?'Je rol in de kamer is aangepast.':action==='community-mute'?(m.mutedUntil?'Je kunt vijf minuten geen berichten plaatsen.':'Je kunt weer berichten plaatsen.'):action==='community-ban'?'Je toegang tot deze kamer is ingetrokken. Neem bij vragen contact op met de host.':'Je bent uit deze kamer verwijderd. Neem bij vragen contact op met de host.',actionUrl:mailUrl(c,'community/'+r.id)});c.closeModal();saveRender();}break;
    case'community-accept':case'community-cancel':case'community-decline':{if(!r||!member(r))break;const x=r.challenges.find(x=>x.id===Number(el.dataset.challenge));if(!x||x.status!=='pending')break;if(action==='community-cancel'){if(x.from!==me&&!isModerator(r))break;x.status='cancelled';playerMail(c,'challenge-cancelled',`challenge:${x.id}:cancelled`,r.clubId,x.to,{actorName:displayName(x.from),opponentName:displayName(x.from),status:'Ingetrokken',actionUrl:mailUrl(c,'community/'+r.id)});saveRender();break;}if(action==='community-decline'){if(x.to!==me)break;x.status='declined';playerMail(c,'challenge-cancelled',`challenge:${x.id}:declined`,r.clubId,x.from,{actorName:displayName(x.to),opponentName:displayName(x.to),status:'Afgewezen',actionUrl:mailUrl(c,'community/'+r.id)});saveRender();break;}if(![x.from,x.to].includes(me)||!canSend(r)||!member(r,x.from)||!member(r,x.to)||blocked(x.from===me?x.to:x.from)){c.toast('Deze uitnodiging is niet meer beschikbaar.');break;}x.status='accepted';const opponent=x.from===me?x.to:x.from;const matchId=c.createGame({opponentId:opponent,startScore:x.startScore,bestOf:x.bestOf,type:x.ranked?'ranked':'practice',setup:'remote',cameraRequired:x.ranked,communityRoomId:r.id});x.matchId=matchId;if(matchId)playerMail(c,'challenge-accepted',`challenge:${x.id}:accepted`,r.clubId,x.from,{actorName:displayName(x.to),opponentName:displayName(x.to),startScore:x.startScore,bestOf:x.bestOf,actionUrl:mailUrl(c,'match/'+matchId)});addSystem(r,`${displayName(x.from)} en ${displayName(x.to)} gaan naar hun wedstrijdkamer.`);c.save();}break;
    default:return false;
  }return true;}
  function error(text){const el=document.getElementById('community-error');if(el)el.textContent=text;else c.toast(text);}
  function handleForm(form,v){const kind=form.dataset.form;if(!kind.startsWith('community-'))return false;init();if(kind==='community-search'){query=String(v.query||'').trim();c.go('community');return true;}if(kind==='community-code'){const r=codeRoom(v.code);if(!r){error('Deze kamercode is niet bekend in deze lokale demo.');return true;}if(!clubAccess(r)){error('Word eerst lid van de club om deze kamer te gebruiken.');return true;}if(r.bans.includes(me)){error('Je bent geblokkeerd voor deze kamer.');return true;}if(!member(r)&&r.members.length>=r.maxMembers){error('Deze kamer zit vol.');return true;}join(r,true);return true;}
    if(kind==='community-create'){const name=String(v.name||'').trim(),max=Number(v.maxMembers),type=String(v.type||'');if(!name||name.length>60||!Object.hasOwn(labels,type)||!Number.isInteger(max)||max<2||max>64){error('Kies een naam, kamertype en maximaal 2 tot 64 personen.');return true;}const friend=Number(v.friend),invitedIds=friend&&friend!==me&&!blocked(friend)&&clubAccess({clubId:activeScope()},friend)&&c.db.players.some(p=>p.id===friend&&p.status==='approved')?[friend]:[];const id=createRoom({name,type,maxMembers:max,description:v.description});const r=roomById(id);r.invitedIds=invitedIds;for(const pid of invitedIds)playerMail(c,'room-invite',`room:${r.id}:invite:${pid}`,r.clubId,pid,{actorName:displayName(me),roomName:r.name,actionUrl:mailUrl(c,'community/'+r.code)});c.save();c.closeModal();c.go('community/'+r.id);c.toast('Je kamer staat klaar.');return true;}
    const r=roomById(v.roomId);if(!r){error('Deze kamer is niet beschikbaar.');return true;}
    if(kind==='community-settings'){if(!isHost(r))return true;const max=Number(v.maxMembers),name=String(v.name||'').trim();if(!name||name.length>60||!Object.hasOwn(labels,v.type)||!Number.isInteger(max)||max<Math.max(2,r.members.length)||max>64){error('Het maximum moet tussen het huidige aantal leden en 64 liggen.');return true;}r.name=name;r.description=String(v.description||'').trim().slice(0,160);r.type=v.type;r.maxMembers=max;r.slowMode=[0,10,30].includes(Number(v.slowMode))?Number(v.slowMode):0;addSystem(r,'De host heeft de kamerinstellingen bijgewerkt.');c.save();c.closeModal();c.render();c.toast('Kamerinstellingen opgeslagen.');return true;}
    if(kind==='community-message'){if(!canSend(r)){c.toast(refusal(r));return true;}const text=String(v.text||'').trim();if(!text||text.length>500){c.toast('Een bericht bevat 1 tot 500 tekens.');return true;}const elapsed=Date.now()-Number(r.lastSentBy[me]||0);if(r.slowMode&&!isModerator(r)&&elapsed<r.slowMode*1000){c.toast(`Wacht nog ${Math.ceil(r.slowMode-elapsed/1000)} seconden voor je volgende bericht.`);return true;}r.messages.push({id:uid(),userId:me,text,date:now(),deleted:false});r.lastSentBy[me]=Date.now();if(r.messages.length>200)r.messages=r.messages.slice(-200);saveRender();return true;}
    if(kind==='community-challenge'){const opponent=Number(v.opponentId),score=Number(v.startScore),bestOf=Number(v.bestOf);if(!canSend(r)||!member(r,opponent)||opponent===me||blocked(opponent)){error(refusal(r)||'Deze tegenstander is niet beschikbaar.');return true;}if(![301,501,701].includes(score)||![1,3,5,7,9].includes(bestOf)){error('Kies een geldige wedstrijdinstelling.');return true;}if(r.challenges.some(x=>x.status==='pending'&&[x.from,x.to].includes(me)&&[x.from,x.to].includes(opponent))){error('Er staat al een open uitdaging tussen jullie.');return true;}const x={id:uid(),from:me,to:opponent,startScore:score,bestOf,ranked:v.ranked==='yes',status:'pending',date:now(),matchId:null};r.challenges.push(x);playerMail(c,'challenge-invite',`challenge:${x.id}:pending`,r.clubId,x.to,{actorName:displayName(x.from),opponentName:displayName(x.from),startScore:x.startScore,bestOf:x.bestOf,roomName:r.name,actionUrl:mailUrl(c,'community/'+r.id)});r.messages.push({id:uid(),userId:me,kind:'challenge',challengeId:x.id,text:'Wedstrijd uitnodiging',date:now(),deleted:false});c.save();c.closeModal();c.render();c.toast('Je uitdaging staat in de kamer.');return true;}
    return false;
  }
  return {init,view,handleAction,handleForm,createRoom};
}
